{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MEDMONGERS_DB.MAPLEMONK.MEDMONGERS_DB_amazon_fact_items_intermediate AS SELECT \'AMAZON\' AS shop_name, \"amazon-order-id\" AS order_id, \"amazon-order-id\" AS order_name, NULL AS customer_id, NULL AS phone, NULL AS tags, NULL AS line_item_id, sku, ASIN AS product_id, currency, case when \"order-status\" in (\'Shipped - Returned to Seller\', \'Shipped - Returning to Seller\',\'Shipped - Rejected by Buyer\',\'Shipped - Damaged\') then 1 else 0 end AS is_refund, upper(\"ship-city\") AS city, upper(\"ship-state\") AS state, \"ship-postal-code\" AS pincode, \"product-name\" AS product_name, \"order-status\" AS order_status, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', \"purchase-date\") AS order_timestamp, ifnull(TRY_CAST(\"item-price\" AS FLOAT),0) AS line_item_sales, ifnull(TRY_CAST(\"shipping-price\" AS FLOAT),0) AS shipping_price, ifnull(TRY_CAST(QUANTITY AS FLOAT),0) AS quantity, ifnull(TRY_CAST(\"item-tax\" AS FLOAT),0) AS tax, div0(ifnull(TRY_CAST(\"item-tax\" AS FLOAT),0),ifnull(TRY_CAST(\"item-tax\" AS FLOAT),0)+ifnull(TRY_CAST(\"item-price\" AS FLOAT),0)) as tax_rate, ifnull(TRY_CAST(\"item-promotion-discount\" AS FLOAT),0) AS discount, div0(ifnull(TRY_CAST(\"item-promotion-discount\" AS FLOAT),0),(1-tax_rate)) AS discount_before_tax, NULL AS gross_sales_after_tax, line_item_sales - discount_before_tax AS gross_sales_before_tax, NULL AS net_sales_before_tax, ifnull(TRY_CAST(\"item-price\" AS FLOAT),0) AS total_sales, \'Amazon\' AS source, NULL AS landing_utm_medium, NULL AS landing_utm_source, NULL AS landing_utm_campaign, NULL AS referring_utm_medium, NULL AS referring_utm_source, NULL AS landing_utm_channel, NULL AS referring_utm_channel, NULL AS final_utm_channel, NULL AS new_customer_flag, NULL AS acquisition_channel, NULL AS acquisition_product, ifnull(TRY_CAST(\"shipping-tax\" AS FLOAT),0) AS shipping_tax, ifnull(TRY_CAST(\"ship-promotion-discount\" AS FLOAT),0) AS ship_promotion_discount, ifnull(TRY_CAST(\"gift-wrap-price\" AS FLOAT),0) AS gift_wrap_price, ifnull(TRY_CAST(\"gift-wrap-tax\" AS FLOAT),0) AS gift_wrap_tax FROM (SELECT *, CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', \"purchase-date\":: DATETIME) as \"Purchase-datetime-PDT\" FROM MEDMONGERS_DB.MAPLEMONK.Amazon_seller_MedMongers_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL ) X ; CREATE OR REPLACE TABLE MEDMONGERS_DB.MAPLEMONK.MEDMONGERS_DB_AMAZON_FACT_ITEMS AS SELECT a.*, upper(coalesce(sm.product_name,sm1.product_name,usm.product_name)) as product_name_final, upper(coalesce(sm.product_category,sm1.product_category,usm.product_category)) as product_category, upper(coalesce(sm.product_sub_category,sm1.product_sub_category)) as product_sub_category, coalesce(sm.landing_cost,sm1.landing_cost) as cogs, coalesce(sm.mrp,sm1.mrp,usm.mrp) as sku_mrp, upper(coalesce(sm.brand,sm1.brand,usm.brand)) as brand, upper(coalesce(sm.commonsku,sm1.commonsku,usm.commonsku)) as commonsku, coalesce(sm.tax_rate,sm1.tax_rate) as final_tax_rate FROM MEDMONGERS_DB.MAPLEMONK.MEDMONGERS_DB_amazon_fact_items_intermediate a left join ( select product_id, upper(sku_code) as commonsku, upper(product_name) as product_name, upper(category) as product_category, upper(sub_category) as product_sub_category, landing_cost, mrp, brand, packaging_cost, tax_rate from medmongers_db.maplemonk.medmongers_final_sku_master where final_marketplace = \'AMAZON\' qualify row_number() over (partition by lower(trim(product_id)) order by channelname) = 1 ) sm on lower(trim(sm.product_id)) = lower(a.product_id) left join ( select channel_sku, upper(sku_code) as commonsku, upper(product_name) as product_name, upper(category) as product_category, upper(sub_category) as product_sub_category, landing_cost, mrp, brand, packaging_cost, tax_rate from medmongers_db.maplemonk.medmongers_final_sku_master where final_marketplace = \'AMAZON\' qualify row_number() over (partition by lower(trim(channel_sku)) order by channelname) = 1 ) sm1 on lower(trim(sm1.channel_sku)) = lower(a.sku) left join ( select channel_sku, product_id, upper(sku_code) as commonsku, upper(product_name) as product_name, upper(category) as product_category, case when cost = \'\' then null else cast(cost as float) end as cost, case when mrp = \'\' then null else cast(mrp as float) end as mrp, brand from medmongers_db.maplemonk.medmongers_unicommerce_sku_master where final_marketplace = \'AMAZON\' qualify row_number() over (partition by channel_sku order by channelname) = 1 ) usm on lower(trim(usm.channel_sku)) = lower(trim(a.sku)) ;",
                    "transaction": true
                }
            ) }}
